//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::string::utf8_get_opt`; the
//! native twin is `benches/native/Bench/StringUtf8GetOpt.lean`.
//! NOT COMPARABLE: Lean's API allocates the `some` at every valid position; the crate returns an
//! Option<u32>, and a translator's cost depends on its Option representation

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::string;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &PosInput, n: u64) -> u64 {
    let (s, ps) = (inp.s.as_bytes(), &inp.ps[..]);
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match string::utf8_get_opt(s, nat_unbox(get_word(ps, x >> 52))) {
                Some(c) => u64::from(c),
                None => 0x110000,
            },
        );
    }
    acc
}

fn main() {
    run(|| pos_input(mixed(), Positions::Any), kernel)
}
